    // POST new data
    app.post('/api/data', (req, res) => {
        const newItem = req.body;
        newItem.id = data.length + 1;
        data.push(newItem);
        res.status(201).json(newItem);
    });

    // PUT (update) data
    app.put('/api/data/:id', (req, res) => {
        const id = parseInt(req.params.id);
