                                // Cache hit
                                cacheHits++;
                                System.out.println("Cache hit for query: " + query);
                            }
                        }
                    }
                    return List.of().iterator(); // Return an empty iterator to avoid errors
                });

        // Get the total number of queries
        long totalQueries = onsiteAttributedData.count();

        // Calculate the hit rate
        double hitRate = (double) cacheHits / totalQueries;

        System.out.println("Total Queries: " + totalQueries);
        System.out.println("Cache Hits: " + cacheHits);
        System.out.println("Cache Misses: " + cacheMisses);
        System.out.println("Cache Hit Rate: " + hitRate);

        spark.stop();
    }
}
