      duration: 0.5,
    }, 'start');

    tl.to($portfolioNext.current, {
      clipPath: 'polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)',
      delay: 0.1,
      duration: 0.5,
    }, 'start');

    tl.set($portfolioCurrent.current, {
      clipPath: 'polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)',
    });

    tl.set($portfolioCurrent.current, {
      css: { backgroundImage: 'url(' + cursor.cursorImage + ')' },
    });

    animationRef.current = requestAnimationFrame(animate);
  };

  // Initial call to start the animation loop
  animationRef.current = requestAnimationFrame(animate);

  // Cleanup function to stop the animation loop when the component unmounts or cursor.cursorImage changes
  return () => {
    if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }
  };
}, [cursor.cursorImage]);
```

Key improvements and explanations:

* **`requestAnimationFrame`:** This is the core of the solution.  `requestAnimationFrame` schedules a function to be called before the next browser repaint.  This is the most efficient way to create animations in the browser because it synchronizes with the browser's rendering pipeline.
* **`animationRef`:**  A `useRef` is used to store the ID returned by `requestAnimationFrame`. This allows us to cancel the animation loop when needed.  Using a ref prevents re-renders when the value changes.
* **`animate` function:** This function contains the animation logic.  It's called repeatedly by `requestAnimationFrame`.
* **Cancellation:**  Before scheduling the next frame, the code checks if a previous frame is already scheduled (`animationRef.current`). If so, it cancels that frame using `cancelAnimationFrame`. This prevents multiple frames from being scheduled if `cursor.cursorImage` changes rapidly.

