func resolve(hostname string) ([]net.IP, error) {
	cacheLock.RLock()
	if ips, ok := cache[hostname]; ok {
		cacheLock.RUnlock()
		return ips, nil
	}
	cacheLock.RUnlock()

	// Try to resolve using forwarders
	for _, forwarder := range forwarders {
		conn, err := net.Dial("udp", forwarder+":53")
		if err != nil {
			log.Printf("Failed to connect to forwarder %s: %v", forwarder, err)
			continue
		}
		defer conn.Close()

		msg := new(dns.Msg)
		msg.SetRequest(hostname, dns.TypeA)

		_, err = msg.WriteTo(conn)
		if err != nil {
			log.Printf("Failed to send query to forwarder %s: %v", forwarder, err)
			continue
		}

		reply, err := dns.ReadReply(conn)
		if err != nil {
			log.Printf("Failed to read reply from forwarder %s: %v", forwarder, err)
			continue
		}

		if reply.Rcode == dns.RcodeSuccess {
			ips := make([]net.IP, 0)
			for _, ans := range reply.Answer {
				if a, ok := ans.(*dns.A); ok {
					ips = append(ips, a.A)
				}
			}

			cacheLock.Lock()
			cache[hostname] = ips
			cacheLock.Unlock()

			return ips, nil
		}
	}

	return nil, fmt.Errorf("failed to resolve %s", hostname)
}

