void loop() {
  String text = Serial.readStringUntil('\n');
  text.toUpperCase(); // Convert to uppercase for easier lookup

  for (int i = 0; i < text.length(); i++) {
    char character = text.charAt(i);

    if (character >= 'A' && character <= 'Z') {
      int index = character - 'A';
      playMorseCode(morseCode[index]);
    } else if (character == ' ') {
      delay(wordDuration); // Space between words
    } else {
      Serial.print("Invalid character: ");
      Serial.println(character);
    }
  }

  Serial.println("\nConversion complete.");
  delay(2000); // Wait for 2 seconds before next input
}

void playMorseCode(const char* code) {
  for (int i = 0; code[i] != '\0'; i++) {
    if (code[i] == '.') {
      tone(buzzerPin, 1000); // Frequency of the buzzer
      delay(dotDuration);
      noTone(buzzerPin);
      delay(symbolDuration - dotDuration);
    } else if (code[i] == '-') {
      tone(buzzerPin, 1000);
      delay(dashDuration);
      noTone(buzzerPin);
      delay(symbolDuration - dashDuration);
    }
  }
  delay(wordDuration); // Space between letters
}
