import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.List;

@Service
public class QueryScheduler {

    @Value("${sql.query.file}")
    private String sqlQueryFile;

    @Value("${output.file}")
    private String outputFile;

    @Value("${database.url}")
    private String databaseUrl;

    @Value("${database.username}")
    private String databaseUsername;

    @Value("${database.password}")
    private String databasePassword;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Scheduled(cron = "0 */5 * * * *") // Runs every 5 minutes
    public void executeQueryAndStoreResults() {
        try {
            String sqlQuery = readSqlQueryFromFile(sqlQueryFile);
            List<String> results = jdbcTemplate.queryForList(sqlQuery, String.class); // Adjust return type as needed

            writeResultsToFile(outputFile, results);

            System.out.println("Query executed and results stored successfully.");

        } catch (IOException e) {
            System.err.println("Error reading SQL query file: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Error executing query or writing results: " + e.getMessage());
        }
    }

    private String readSqlQueryFromFile(String filePath) throws IOException {
        // Read the SQL query from the file
        return java.nio.file.Files.readString(java.nio.file.Paths.get(filePath));
    }

    private void writeResultsToFile(String filePath, List<String> results) throws IOException {
        // Write the results to the output file
        try (FileWriter writer = new FileWriter(filePath, true)) { // Append to file
            for (String result : results) {
                writer.write(result + "\n");
            }
        }
    }
}
